// ARR - Success rate. Thresholds come from the report (section 5): set from your 30-day baseline.
const CONFIG = {
  window_hours: 24,             // rolling window
  max_failure_rate: 0.05,       // default: alert above 5% failed runs
  min_runs: 10,                 // ignore workflows with fewer runs in the window
  per_workflow: {},             // { 'aBc123': 0.10 } sets one workflow's own threshold, by workflow id
  ignore: [],                   // workflow ids to leave out
};

const since = Date.now() - CONFIG.window_hours * 3600000;
const runs = $input.all().map(i => i.json).filter(e => e && e.id !== undefined);
const by = {};
for (const e of runs) {
  if (CONFIG.ignore.includes(e.workflowId) || e.workflowId === $workflow.id) continue;
  if (!['success', 'error', 'crashed'].includes(e.status)) continue;
  if (new Date(e.startedAt).getTime() < since) continue;
  const w = (by[e.workflowId] = by[e.workflowId] || { total: 0, failed: 0, ids: [] });
  w.total += 1;
  if (e.status !== 'success') { w.failed += 1; if (w.ids.length < 5) w.ids.push(e.id); }
}
const problems = [];
for (const [id, w] of Object.entries(by)) {
  const limit = CONFIG.per_workflow[id] ?? CONFIG.max_failure_rate;
  const rate = w.failed / w.total;
  if (w.total >= CONFIG.min_runs && rate > limit) {
    problems.push(`workflow ${id} had ${w.failed} of ${w.total} runs fail (${(rate * 100).toFixed(1)}%, limit ${(limit * 100).toFixed(1)}%; e.g. executions ${w.ids.join(', ')})`);
  }
}
if (problems.length) {
  throw new Error(`ARR - Success rate failed, ${problems.length} workflow(s) over threshold in the last ${CONFIG.window_hours} h. ${problems.join('; ')}`);
}
return [{ json: { ok: true, workflows: Object.keys(by).length, window_hours: CONFIG.window_hours } }];
